function fallbackExample(item, details) {
  const lead = details.summary || details.paragraphs?.[0] || item.title
  const templates = {
    traps: `Группа сталкивается с ловушкой «${item.title}». Сначала персонажи получают возможность заметить её признаки, затем выбирают способ обхода или обезвреживания; эффект применяется только при указанном срабатывании.`,
    'magic-items': `Персонаж получает «${item.title}». До применения группа проверяет настройку, способ активации и ограничения предмета, а затем разрешает его эффект в указанный момент.`,
    'magical-contagions': `После контакта с источником заражения «${item.title}» Мастер отмечает начальный момент, применяет спасброски и симптомы по описанию, а лечение отслеживает отдельно.`,
    hazards: `Герой входит в область опасности «${item.title}». Мастер сообщает заметные признаки, определяет момент воздействия и применяет предусмотренную защиту или последствия.`,
    'weapon-properties': `Персонаж атакует оружием со свойством «${item.title}». Свойство применяется только после проверки его точного условия и не меняет остальные части атаки.`,
    treasures: `Группа находит ценность категории «${item.title}». Мастер описывает качество и происхождение, после чего номинальная стоимость используется для награды или переговоров о продаже.`,
    'environmental-effects': `Во время путешествия начинает действовать эффект «${item.title}». Мастер учитывает длительность, защитное снаряжение и момент, когда правило требует спасбросок или иной эффект.`,
    abilities: `Ситуация проверяет качество «${item.title}»: игрок описывает подход, а Мастер решает, достаточно ли автоматического результата или нужен тест к20 с соответствующим модификатором.`,
    attitudes: `Существо проявляет ${item.title.toLocaleLowerCase('ru')} отношение. Это меняет проверку Влияния, но решение о том, возможна ли сама просьба, принимается отдельно.`
  }

  return templates[item.category]
    || `В игровой сцене возникает термин «${item.title}»: ${lead} Сначала установите, выполнены ли его условия, затем примените эффект в точный момент, указанный правилом.`
}

function fallbackNuance(item) {
  return NUANCES[item.category]
    || `Не переносите свойства термина «${item.title}» на похожую ситуацию автоматически. Сверьте его условия с конкретной способностью, предметом, существом или эффектом: более узкий текст может изменить общее правило.`
}

export function buildGlossaryGuidance(item, details) {
  const profile = PROFILES[item.category] || PROFILES.general
  const example = EXAMPLES[item.id] || fallbackExample(item, details)
  const gm = ACTION_GM[item.id] || profile.gm
  const nuance = NUANCES[item.id] || fallbackNuance(item)

  return [
    section(profile.exampleTitle, 'example', [example]),
    section(profile.gmTitle, 'gm', [gm]),
    section(profile.nuanceTitle, 'nuance', [nuance])
  ]
}
